import { useMutation, type UseMutationOptions } from "@tanstack/react-query";
import { createCategoryHandler } from "../handlers/createCategoryHandler";
import type { ApiError } from "../runtime/client";
import type { CreateCategoryRequest } from "../types/CreateCategoryRequest";

type Data = Awaited<ReturnType<typeof createCategoryHandler>>;
type Vars = CreateCategoryRequest;

export function useCreateCategory(
  options?: Omit<UseMutationOptions<Data, ApiError, Vars>, "mutationFn">,
) {
  return useMutation<Data, ApiError, Vars>({
    mutationFn: (vars) => createCategoryHandler(vars),
    ...options,
  });
}
